<script setup lang="ts">
import { solveScroll,scrollNames,scrollMasks } from '~/utils/puzzles.mjs'
const {state,change,undo,reset,canUndo,saveError}=usePuzzleState('scroll')
const following=ref(false)
const solution=computed(()=>solveScroll(state.value.board))
function tap(i:number) { change({board:state.value.board^(following.value?scrollMasks[i]:1<<i)}) }
</script>
<template><div class="puzzle"><p>Match the scrolls sticking <strong>OUT</strong> of the wall. The highlighted cells below are the scrolls to shoot.</p><div class="p-row"><button :aria-pressed="!following" @click="following=false">Edit observed board</button><button :aria-pressed="following" @click="following=true">Follow moves</button></div><div class="p-board" style="grid-template-columns:repeat(3,1fr)"><button v-for="(name,i) in scrollNames" :key="name" :aria-label="`${name}: ${state.board & (1<<i)?'out':'in'}${solution?.includes(i)?', shoot this scroll':''}`" :aria-pressed="!!(state.board & (1<<i))" @click="tap(i)"><small>{{ name }}</small><strong>{{ state.board & (1<<i)?'OUT':'IN' }}</strong><span v-if="solution?.includes(i)">◎ Shoot</span></button></div><div class="p-result" aria-live="polite"><p v-if="state.board===0"><strong>All IN.</strong> Collect the Pestle and Death Records.</p><p v-else-if="solution===null">This board has no solution under the verified rule. Recheck which scrolls are OUT.</p><template v-else><strong>Shoot {{ solution.length }} scroll{{ solution.length===1?'':'s' }} · any order</strong><p>{{ solution.map((n:number)=>scrollNames[n]).join(' → ') }}</p></template></div><p class="p-muted">Each shot toggles that scroll and its horizontal/vertical neighbours. “Follow moves” simulates shots; you can also read the complete answer without tracking each shot.</p><PuzzleActions :can-undo="canUndo" :save-error="saveError" @undo="undo" @reset="reset(); following=false" /></div></template>
